"use strict";(globalThis.webpackChunkeo_glossary=globalThis.webpackChunkeo_glossary||[]).push([[96029],{6998(e){e.exports=JSON.parse('{"tag":{"label":"LSI-VC","permalink":"/eo-glossary/tags/lsi-vc","allTagsPath":"/eo-glossary/tags","count":16,"items":[{"id":"terms/analysis_ready_data","title":"Analysis Ready Data","description":"Processed data product geometrically referenced and minimally corrected to enable direct use without additional user processing.","permalink":"/eo-glossary/terms/analysis_ready_data"},{"id":"terms/anthroposphere","title":"Anthroposphere","description":"One of the Earth spheres consisting predominantly of matter processed by humans, such as construction wood, bricks, concrete, asphalt, glass, or plastics.","permalink":"/eo-glossary/terms/anthroposphere"},{"id":"terms/classification_system","title":"Classification System","description":"Nomenclature used to classify Information into categorical thematic classes (e.g., EUNIS, MAES ecosystems, Corine Land Cover, LCCS).","permalink":"/eo-glossary/terms/classification_system"},{"id":"terms/classification_system_levels","title":"Classification System Levels","description":"Levels in a hierarchical Classification System.","permalink":"/eo-glossary/terms/classification_system_levels"},{"id":"terms/georectifying","title":"Georectifying","description":"Correcting for positional displacement with respect to the surface of the Earth.","permalink":"/eo-glossary/terms/georectifying"},{"id":"terms/geosphere","title":"Geosphere","description":"The masses of minerals that constitute planet Earth.","permalink":"/eo-glossary/terms/geosphere"},{"id":"terms/ground_sampling_distance","title":"Ground Sampling Distance","description":"linear distance between pixel centres on the ground.","permalink":"/eo-glossary/terms/ground_sampling_distance"},{"id":"terms/interferometric_baseline","title":"Interferometric Baseline","description":"Accurate determination of orbital distances between satellites with compatible orbits, required for SAR and differential interferometry applications.","permalink":"/eo-glossary/terms/interferometric_baseline"},{"id":"terms/interoperable_products","title":"Interoperable Products","description":"Set of two or more ARD products sufficiently documented to enable processing across a continuum of geometric and/or radiometric standards for direct quantitative comparison.","permalink":"/eo-glossary/terms/interoperable_products"},{"id":"terms/lithosphere","title":"Lithosphere","description":"The solid, inanimate outer layer of the Geosphere.","permalink":"/eo-glossary/terms/lithosphere"},{"id":"terms/minimum_mapping_unit","title":"Minimum Mapping Unit","description":"The area of the smallest Feature that is still represented on a map.","permalink":"/eo-glossary/terms/minimum_mapping_unit"},{"id":"terms/minimum_mapping_width","title":"Minimum Mapping Width","description":"The width of the smallest linear Feature that is still represented on a map.","permalink":"/eo-glossary/terms/minimum_mapping_width"},{"id":"terms/resample","title":"Resample","description":"Technique of transforming a digital image to alter resolution, orientation, or sampling points for applications in medical, industrial, and remote sensing contexts.","permalink":"/eo-glossary/terms/resample"},{"id":"terms/scene","title":"Scene","description":"Subset of instrument acquisition data segmented by time across the swath.","permalink":"/eo-glossary/terms/scene"},{"id":"terms/thematic_resolution","title":"Thematic Resolution","description":"Level of categorical detail of information expressed by the number of classes.","permalink":"/eo-glossary/terms/thematic_resolution"},{"id":"terms/thematic_uncertainty","title":"Thematic Uncertainty","description":"Uncertainty associated with the method of classification.","permalink":"/eo-glossary/terms/thematic_uncertainty"}],"unlisted":false}}')}}]);